import { ChapterComposer } from './solution';
import type { ChapterDraft } from './solution';

function ok(value: boolean, message: string): void {
  if (!value) throw new Error(message);
}

function equal<T>(actual: T, expected: T, message: string): void {
  if (actual !== expected) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
}

function throwsError(fn: () => void, message: string): void {
  try {
    fn();
  } catch (error) {
    if (error instanceof Error) return;
    throw new Error(`${message}: non-Error thrown`);
  }
  throw new Error(`${message}: did not throw`);
}

const seed: ChapterDraft = {
  name: '  Chapter One  ',
  text: '  Original text  ',
  references: [' Ref A ', 'Ref B']
};
let submitted: ChapterDraft | undefined;
let submitCount = 0;
const composer = new ChapterComposer(seed, draft => {
  submitCount += 1;
  submitted = draft;
  draft.name = 'callback mutation';
  draft.references.push('callback addition');
});
seed.name = 'changed seed';
seed.text = 'changed seed text';
seed.references[0] = 'changed seed reference';
seed.references.push('new seed reference');

equal(JSON.stringify(composer.snapshot()), JSON.stringify({
  name: '  Chapter One  ',
  text: '  Original text  ',
  references: [' Ref A ', 'Ref B']
}), 'seed and references must be copied and accepted strings preserved');

const firstSnapshot = composer.snapshot();
firstSnapshot.name = 'mutated snapshot';
firstSnapshot.references[0] = 'mutated snapshot reference';
firstSnapshot.references.push('extra');
equal(composer.snapshot().name, '  Chapter One  ', 'snapshot object is fresh');
equal(composer.snapshot().references.join(','), ' Ref A ,Ref B', 'snapshot references are fresh');

const replacement = [' New Ref '];
composer.update({ text: ' Updated ', references: replacement });
replacement[0] = 'changed replacement';
replacement.push('later');
equal(JSON.stringify(composer.snapshot()), JSON.stringify({
  name: '  Chapter One  ',
  text: ' Updated ',
  references: [' New Ref ']
}), 'update merges scalar fields and copies replacement references');

const saved = composer.save();
ok(saved !== composer.snapshot(), 'save returns a fresh object');
saved.text = 'mutated saved text';
saved.references.push('mutated saved reference');
equal(composer.snapshot().text, ' Updated ', 'save result cannot mutate internal state');
equal(composer.snapshot().references.length, 1, 'save result references are isolated');
composer.submit();
equal(submitCount, 1, 'submit callback is called once');
ok(submitted !== undefined, 'submit supplies a draft');
equal(composer.snapshot().name, '  Chapter One  ', 'callback object mutation cannot change internal name');
equal(composer.snapshot().references.join(','), ' New Ref ', 'callback array mutation cannot change internal references');

const emptyReferences = new ChapterComposer({ name: 'Name', text: 'Text', references: [] }, () => undefined);
ok(emptyReferences.canSubmit(), 'empty references array is valid');
emptyReferences.save();

const invalid = new ChapterComposer(undefined, () => { throw new Error('must not submit'); });
ok(!invalid.canSubmit(), 'default empty draft is invalid');
throwsError(() => invalid.save(), 'empty draft cannot save');
throwsError(() => invalid.submit(), 'empty draft cannot submit');
invalid.update({ name: 'Name only' });
ok(!invalid.canSubmit(), 'both name and text are required');
invalid.update({ name: ' ', text: 'Text' });
ok(!invalid.canSubmit(), 'whitespace name is invalid');
invalid.update({ name: 'Name', text: '\t', references: [] });
ok(!invalid.canSubmit(), 'whitespace text is invalid');
invalid.update({ text: 'Text', references: ['good', '  '] });
ok(!invalid.canSubmit(), 'blank reference is invalid');
throwsError(() => invalid.save(), 'invalid reference prevents save');
throwsError(() => invalid.submit(), 'invalid reference prevents submit');

